(7645043, 1242528, 181505, '<td valign="top">Great capture!</td>', 'Great capture!', '2019-11-01 09:09:53.000000', NULL, 1),
(7645046, 1242726, 65234, '<td valign="top">Love the light and composition and I do love a nice walk in the woods this time of year. First thing I thought of when I saw this was that the colors could be warmer for this scene. A light orange overlay would make this feel more spectacularly autumnal to me. Or some similar way of warming it up. My 2 cents, FWIW.</td>', 'Love the light and composition and I do love a nice walk in the woods this time of year. First thing I thought of when I saw this was that the colors could be warmer for this scene. A light orange overlay would make this feel more spectacularly autumnal to me. Or some similar way of warming it up. My 2 cents, FWIW.', '2019-11-01 09:30:50.000000', NULL, 1),
(7645047, 1242208, 65234, '<td valign="top">Pretty scene. A little dark on my screen.</td>', 'Pretty scene. A little dark on my screen.', '2019-11-01 09:32:48.000000', NULL, 1),
(7645048, 1242713, 65234, '<td valign="top">Love the color of these in the Fall. Hate the invasiveness of the vine in my garden. Nice, creamy bokeh here.</td>', 'Love the color of these in the Fall. Hate the invasiveness of the vine in my garden. Nice, creamy bokeh here.', '2019-11-01 09:34:05.000000', NULL, 1),
(7645049, 1242663, 65234, '<td valign="top">Ewww. Poor rat. Good detail on the snake''s head.</td>', 'Ewww. Poor rat. Good detail on the snake''s head.', '2019-11-01 09:41:11.000000', NULL, 1),
(7645050, 1242476, 65234, '<td valign="top">Ooh, fabulous capture of that light. The subject behind it is ordinary, but irrelevant. I can''t look at anything but the light.</td>', 'Ooh, fabulous capture of that light. The subject behind it is ordinary, but irrelevant. I can''t look at anything but the light.', '2019-11-01 09:42:52.000000', NULL, 1),
(7645051, 1242637, 65234, '<td valign="top">Pretty scene. Might like a bit more detail in the darker areas, if that''s possible.</td>', 'Pretty scene. Might like a bit more detail in the darker areas, if that''s possible.', '2019-11-01 09:44:50.000000', NULL, 1),
